#!/usr/bin/env node
// scripts/sidebar-coverage.mjs
//
// Checks that every doc belongs to exactly one section sidebar (sidebars.js).
// The navbar tabs are `type: 'docSidebar'` items, so a doc in no sidebar has no
// active tab and no left navigation, and a doc in two sidebars highlights an
// arbitrary tab. Run after `docusaurus build` (it is part of `npm run gate`):
//
//   node scripts/sidebar-coverage.mjs
//
// It reads the docs plugin's generated data in .docusaurus/ rather than
// re-implementing ID resolution, so frontmatter `id:`, autogenerated
// directories, and category links are resolved exactly as Docusaurus does.
// Docs with `unlisted` or `draft` frontmatter are ignored, as are the pages in
// ALLOWED_ORPHANS below (not in any sidebar before the section split; adding
// them is an IA decision, not something this check should force).
import fs from "node:fs";
import path from "node:path";

const GENERATED = path.resolve(".docusaurus/docusaurus-plugin-content-docs/default");
const SIDEBARS = path.resolve("sidebars.js");

const EXPECTED_SIDEBARS = [
  "getStarted",
  "concepts",
  "modeling",
  "enforce",
  "aiAgents",
  "sdks",
  "integrations",
  "operate",
];

const ALLOWED_ORPHANS = new Set([
  "home", // `/` is the entry page; it renders without a sidebar by design.
  "authentication/fusionauth",
  "concepts/deployment-options",
  "overview/connecting-your-app",
  "overview/get-api-key",
  "overview/perform-a-local-policy-check",
  "overview/run-pdp",
  "overview/sync-application-data-into-permit",
]);

function fail(msg) {
  console.error(`sidebar-coverage: ${msg}`);
  process.exit(1);
}

if (!fs.existsSync(GENERATED)) fail(`${GENERATED} not found; run \`docusaurus build\` first.`);

const readJson = (f) => JSON.parse(fs.readFileSync(f, "utf8"));

// The version props file is the one carrying docsSidebars; take the newest in
// case an older build left a differently-hashed copy behind.
const versionFile = fs
  .readdirSync(path.join(GENERATED, "p"))
  .map((f) => path.join(GENERATED, "p", f))
  .filter((f) => f.endsWith(".json"))
  .map((f) => ({ f, mtime: fs.statSync(f).mtimeMs }))
  .sort((a, b) => b.mtime - a.mtime)
  .find(({ f }) => readJson(f).version?.docsSidebars);
if (!versionFile) fail("no generated version data with docsSidebars found.");
if (versionFile.mtime < fs.statSync(SIDEBARS).mtimeMs) {
  fail("generated data is older than sidebars.js; rebuild before checking.");
}
const { docsSidebars } = readJson(versionFile.f).version;

// Every doc's metadata file; skip leftovers whose source file was deleted.
const docs = fs
  .readdirSync(GENERATED)
  .filter((f) => f.startsWith("site-docs-") && f.endsWith(".json"))
  .map((f) => readJson(path.join(GENERATED, f)))
  .filter((d) => fs.existsSync(d.source.replace(/^@site\//, "")));
const idByPermalink = new Map(docs.map((d) => [d.permalink, d.id]));

// doc id -> set of sidebars that list it (as a doc link or a category link).
const membership = new Map();
function walk(items, sidebar) {
  for (const item of items) {
    let id = item.docId;
    if (!id && item.type === "category" && item.href) id = idByPermalink.get(item.href);
    if (id) {
      if (!membership.has(id)) membership.set(id, new Set());
      membership.get(id).add(sidebar);
    }
    if (item.items) walk(item.items, sidebar);
  }
}
for (const [name, items] of Object.entries(docsSidebars)) walk(items, name);

const problems = [];

const actual = Object.keys(docsSidebars);
const missingSidebars = EXPECTED_SIDEBARS.filter((s) => !actual.includes(s));
const extraSidebars = actual.filter((s) => !EXPECTED_SIDEBARS.includes(s));
if (missingSidebars.length) problems.push(`missing sidebars: ${missingSidebars.join(", ")}`);
if (extraSidebars.length) problems.push(`unexpected sidebars: ${extraSidebars.join(", ")}`);

const listed = docs.filter((d) => !d.unlisted && !d.draft);
const orphans = listed.filter((d) => !membership.has(d.id) && !ALLOWED_ORPHANS.has(d.id));
const shared = [...membership].filter(([, s]) => s.size > 1);

for (const d of orphans) problems.push(`in no sidebar: ${d.id} (${d.source})`);
for (const [id, s] of shared) problems.push(`in ${s.size} sidebars (${[...s].join(", ")}): ${id}`);

const counts = Object.fromEntries(
  actual.map((s) => [s, [...membership.values()].filter((set) => set.has(s)).length])
);

if (problems.length) {
  console.error(problems.map((p) => `  - ${p}`).join("\n"));
  fail(`${problems.length} problem(s).`);
}
console.log(
  `sidebar-coverage: OK. ${membership.size} docs across ${actual.length} sidebars ` +
    `(${Object.entries(counts)
      .map(([s, n]) => `${s} ${n}`)
      .join(", ")}); ` +
    `${listed.length - membership.size} allowed orphans.`
);
